:root {
  color-scheme: light;
  --color-text: #172554;
  --color-surface: #ffffff;
  --color-border: #cbd5e1;
}

.card {
  color: var(--color-text);
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  padding: 1rem;
}

[data-theme="dark"] {
  color-scheme: dark;
  --color-text: #e2e8f0;
  --color-surface: #0f172a;
  --color-border: #475569;
}
